INSERT INTO TFEE_PRED_RESULT (
    PRED_ID, SBJT_ID, ORGN_ID, PRED_AT, TOTAL_SCORE, GRADE_CD, RULE_VERSION, RECOMM_ACTION
) VALUES (
    #{predId}, #{sbjtId}, #{orgnId}, SYSTIMESTAMP,
    #{totalScore}, #{gradeCd}, #{ruleVersion}, #{recommAction}
)

mapper.select:
SELECT * FROM (
    SELECT R.* FROM TFEE_PRED_RESULT R
     WHERE R.SBJT_ID = #{sbjtId} AND R.ORGN_ID = #{orgnId}
     ORDER BY R.PRED_AT DESC
) WHERE ROWNUM = 1

SELECT * FROM (
    SELECT R.*, ROW_NUMBER() OVER (ORDER BY R.TOTAL_SCORE DESC, R.PRED_AT DESC) RN
      FROM TFEE_PRED_RESULT R
     WHERE R.GRADE_CD IN
         #{g}
)
WHERE RN BETWEEN #{offset}+1 AND #{offset}+#{limit}

SELECT COUNT(*) FROM TFEE_PRED_RESULT
 WHERE GRADE_CD IN
     #{g}
